const item = $input.first().json;
const answerRaw = String(item.output || '').trim();
const steps = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];

const normalize = (u) => {
  const s = String(u).trim();
  const m = s.match(/^(https?):\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?/i);
  if (!m) return null;
  const path = m[3].replace(/\/+$/, '');
  const params = (m[4] || '').replace(/^\?/, '').split('&').filter((p) => p && !p.toLowerCase().startsWith('utm_'));
  return (m[1] + '://' + m[2] + path + (params.length ? '?' + params.join('&') : '')).toLowerCase();
};

const hostOf = (u) => {
  const m = String(u).match(/^https?:\/\/([^\/?#]+)/i);
  return m ? m[1] : String(u);
};

const fromStructured = (value, out) => {
  if (Array.isArray(value)) { value.forEach((v) => fromStructured(v, out)); return; }
  if (value && typeof value === 'object') {
    if (typeof value.url === 'string') {
      out.push({ url: value.url, title: String(value.title || ''), content: String(value.content || ''), date: value.published_date || value.publishedDate || null });
    }
    Object.keys(value).forEach((k) => { if (value[k] && typeof value[k] === 'object') fromStructured(value[k], out); });
  }
};

const parseObservation = (obs) => {
  const out = [];
  let data = obs;
  if (typeof data === 'string') {
    const t = data.trim();
    if (t.startsWith('{') || t.startsWith('[')) {
      try { data = JSON.parse(t); } catch (e) { data = t; }
    }
  }
  if (typeof data === 'string') {
    const re = /(?:"url"|url)\s*[:=]\s*"?(https?:\/\/[^\s"',\]\)}]+)/gi;
    let m;
    while ((m = re.exec(data)) !== null) { out.push({ url: m[1], title: '', content: '', date: null }); }
    return out;
  }
  fromStructured(data, out);
  return out;
};

const registry = [];
const byKey = {};
const register = (r) => {
  const key = normalize(r.url);
  if (!key) return false;
  if (!byKey[key]) {
    const src = { id: registry.length + 1, title: r.title, url: r.url, snippet: r.content, published_date: r.date ? String(r.date) : null };
    byKey[key] = src;
    registry.push(src);
  } else if (!byKey[key].title && r.title) {
    byKey[key].title = r.title;
  }
  return true;
};

const events = [];
steps.forEach((s) => {
  const input = s && s.action ? s.action.toolInput : null;
  const q = input && typeof input === 'object' ? (input.query || input.input) : null;
  events.push(q ? 'Searching the web: "' + q + '"' : 'Searching the web');
  const found = parseObservation(s ? s.observation : null);
  let n = 0;
  found.forEach((r) => { if (register(r)) n += 1; });
  events.push(n > 0 ? 'Reviewing ' + n + ' result' + (n === 1 ? '' : 's') : 'No useful results found');
});

const mapping = {};
const cited = [];
const invalid = [];
let text = answerRaw.replace(/([ \t]*)\[{1,2}\s*(https?:\/\/[^\]\s]+)\s*\]{1,2}/g, (m, lead, url) => {
  const key = normalize(url);
  const src = key ? byKey[key] : null;
  if (!src) { invalid.push(url); return ''; }
  if (!mapping[src.id]) { mapping[src.id] = cited.length + 1; cited.push(src); }
  return lead + '[' + mapping[src.id] + ']';
});
text = text.replace(/[ \t]+([.,;:!?])/g, '$1').trim();

const sources = cited.map((s, i) => ({ id: i + 1, title: s.title || hostOf(s.url), url: s.url, published_date: s.published_date }));

const base = {
  searches_completed: steps.length,
  retrieved_count: registry.length,
  events,
  disclaimer: 'Web search results can be incomplete, biased or out of date. Open the sources and verify anything important.'
};

let result;
if (steps.length === 0) {
  result = { status: 'search_failed', answer: '', sources: [], warnings: [], message: 'The web search did not run, so no sourced answer can be given. Please try again.', ...base };
} else if (registry.length === 0) {
  result = { status: 'no_sources', answer: '', sources: [], warnings: [], message: 'The search ran but returned no useful sources. Try rephrasing or narrowing your question.', ...base };
} else if (!text) {
  result = { status: 'search_failed', answer: '', sources: [], warnings: [], message: 'The model returned an empty answer. Please try again.', ...base };
} else {
  const warnings = [];
  if (invalid.length > 0) warnings.push('Some citation markers pointed to sources that were never retrieved and were removed.');
  if (sources.length === 0) warnings.push('The answer contains no valid citations. Treat it as unverified.');
  events.push('Writing the answer');
  result = { status: 'ok', answer: text, sources, warnings, message: '', ...base };
}

return [{ json: result }];
